import{_ as d,o as e,c as r,a2 as o}from"./chunks/framework.Bg-Zxr5O.js";const S=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/CTABLES-Implicit-Categories.md","filePath":"manual-zh/CTABLES-Implicit-Categories.md","lastUpdated":1785684581000}'),a={name:"manual-zh/CTABLES-Implicit-Categories.md"};function c(i,t,n,l,s,E){return e(),r("div",null,[...t[0]||(t[0]=[o(`<h4 id="_15-7-5-2-隐式类别" tabindex="-1">15.7.5.2 隐式类别 <a class="header-anchor" href="#_15-7-5-2-隐式类别" aria-label="Permalink to &quot;15.7.5.2 隐式类别&quot;">​</a></h4><p>在没有显式类别列表的情况下，<code>CATEGORIES</code> 允许通过 <code>KEY</code>、<code>ORDER</code> 和 <code>MISSING</code> 来指定如何选择并排序类别。</p><p><code>KEY</code> 设置指定排序键。默认情况下，或使用 <code>KEY=VALUE</code> 时，类别按默认值排序。类别也可以按值标签排序（<code>KEY=LABEL</code>），或按汇总函数的值排序，例如 <code>KEY=COUNT</code>。</p><p>默认情况下，或使用 <code>ORDER=A</code> 时，类别按升序排序。指定 <code>ORDER=D</code> 则按降序排序。</p><p>默认情况下，或使用 <code>MISSING=EXCLUDE</code> 时，用户缺失值被排除。指定 <code>MISSING=INCLUDE</code> 可包含用户缺失值。系统缺失值始终被排除。</p><p>以下示例语法和输出展示了 <code>MISSING=INCLUDE</code> 如何使缺失值被包含在类别列表中。</p><pre><code>CTABLES /TABLE freqOfDriving.
CTABLES /TABLE freqOfDriving
        /CATEGORIES VARIABLES=freqOfDriving MISSING=INCLUDE.
</code></pre><table tabindex="0"><thead><tr><th></th><th></th><th>Count</th></tr></thead><tbody><tr><td>1. How often do you usually drive a car or other motor vehicle?</td><td>Every day</td><td>4667</td></tr><tr><td>Several days a week</td><td>1274</td><td></td></tr><tr><td>Once a week or less</td><td>361</td><td></td></tr><tr><td>Only certain times a year</td><td>130</td><td></td></tr><tr><td>Never</td><td>540</td><td></td></tr><tr><td></td><td></td><td>Count</td></tr><tr><td>1. How often do you usually drive a car or other motor vehicle?</td><td>Every day</td><td>4667</td></tr><tr><td>Several days a week</td><td>1274</td><td></td></tr><tr><td>Once a week or less</td><td>361</td><td></td></tr><tr><td>Only certain times a year</td><td>130</td><td></td></tr><tr><td>Never</td><td>540</td><td></td></tr><tr><td>Don&#39;t know</td><td>8</td><td></td></tr><tr><td>Refused</td><td>19</td><td></td></tr></tbody></table>`,8)])])}const _=d(a,[["render",c]]);export{S as __pageData,_ as default};
